        count = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if bfs(grid, i, j):
                    count += 1
        return count

class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        if not left: return 0
        i = 0
        cur = left
        while cur + (cur & -cur) <= right:
            cur += cur & -cur
            left &= cur
        return left

